insert into sources (code, name, kind, base_url, docs_url, auth, countries, license, attribution, redistributable, published_by, description) values
  ('ban',                'Base Adresse Nationale',              'api',      'https://api-adresse.data.gouv.fr/',   'https://adresse.data.gouv.fr/api-doc/adresse',                     'none',    '{FR}', 'Licence Ouverte 2.0', '© BAN — Base Adresse Nationale',          true,  'pack:fr', 'The national address register: search as you type and reverse geocoding, with house-number precision. Read by formats/geocoding/ban.ts.'),
  ('geo_api_gouv',       'API Découpage administratif',         'api',      'https://geo.api.gouv.fr/',             'https://geo.api.gouv.fr/decoupage-administratif',                  'none',    '{FR}', 'Licence Ouverte 2.0', '© Etalab',                                true,  'pack:fr', 'Communes, departments and regions, with their codes and boundaries.'),
  ('cadastre',           'Cadastre (PCI vecteur, Etalab)',      'file',     'https://cadastre.data.gouv.fr/',       'https://cadastre.data.gouv.fr/datasets/cadastre-etalab',           'none',    '{FR}', 'Licence Ouverte 2.0', '© DGFiP — Etalab',                        true,  'pack:fr', 'Parcels, building footprints and sections of the cadastre, by municipality, as GeoJSON.'),
  ('bd_topo',            'BD TOPO (IGN)',                       'file',     'https://geoservices.ign.fr/bdtopo',    'https://geoservices.ign.fr/documentation/donnees/vecteur/bdtopo',  'none',    '{FR}', 'Licence Ouverte 2.0', '© IGN',                                   true,  'pack:fr', 'The national topographic database: buildings with height and use, roads, land use, administrative limits.'),
  ('rnb',                'Référentiel National des Bâtiments',  'api',      'https://rnb-api.beta.gouv.fr/',        'https://rnb.beta.gouv.fr/',                                        'none',    '{FR}', 'Licence Ouverte 2.0', '© RNB — DINUM / IGN / CSTB / ADEME',      true,  'pack:fr', 'One stable identifier per building, with its footprint and the addresses and parcels it links to.'),
  ('sirene',             'API Sirene (INSEE)',                  'api',      'https://api.insee.fr/',                'https://www.sirene.fr/',                                           'api_key', '{FR}', 'Licence Ouverte 2.0', '© INSEE',                                 true,  'pack:fr', 'The register of companies and establishments: SIREN, SIRET, legal form, activity, addresses.'),
  ('legifrance',         'Légifrance',                          'registry', 'https://www.legifrance.gouv.fr/',      'https://www.legifrance.gouv.fr/contenu/pied-de-page/open-data-et-api', 'none', '{FR}', 'Licence Ouverte 2.0', '© DILA',                                  true,  'pack:fr', 'The official register of French law: consolidated codes, laws, decrees and orders. The legal sources of this pack point to it.'),
  ('enedis_open_data',   'Enedis Open Data',                    'api',      'https://data.enedis.fr/',              'https://data.enedis.fr/pages/accueil/',                            'none',    '{FR}', 'Licence Ouverte 2.0', '© Enedis',                                true,  'pack:fr', 'Aggregated consumption and production by municipality and IRIS, grid capacities, energy-sharing operations in service.'),
  ('enedis_data_connect','Enedis Data Connect (SGE)',           'api',      'https://gw.ext.prod-sandbox.api.enedis.fr/', 'https://datahub-enedis.fr/data-connect/',                     'mandate', '{FR}', 'Enedis Data Connect terms', '© Enedis',                          false, 'pack:fr', 'A customer''s meter data (daily index, 30-minute load curve, contract) read by a third party with the customer''s consent, per PRM. Kept for the consent''s duration, never passed on.'),
  ('odre',               'Open Data Réseaux Énergies',          'api',      'https://odre.opendatasoft.com/',       'https://odre.opendatasoft.com/pages/accueil/',                     'none',    '{FR}', 'Licence Ouverte 2.0', '© ODRÉ — RTE, Enedis, GRTgaz, GRDF…',     true,  'pack:fr', 'Datasets of the French energy networks: generation, consumption, exchanges, operators'' areas, energy communities.'),
  ('operat',             'OPERAT (ADEME)',                      'registry', 'https://operat.ademe.fr/',             'https://operat.ademe.fr/#/public/home',                            'api_key', '{FR}', 'Terms of OPERAT', '© ADEME',                                     false, 'pack:fr', 'The platform where tertiary buildings of 1 000 m² and more declare their yearly consumption under the Éco Énergie Tertiaire scheme.');
insert into id_schemes (code, name, pattern, url_template, source_code, published_by, description) values
  ('insee',       'Code INSEE',          '^[0-9][0-9AB][0-9]{3}$',                     null,                                                              'geo_api_gouv', 'pack:fr', 'The code of a French municipality in the national statistics register (code commune INSEE): the level at which the distribution operator, planning rules and most datasets are decided.'),
  ('prm',         'PRM / PDL',           '^[0-9]{14}$',                                null,                                                              null,           'pack:fr', 'The 14-digit metering point identifier of the French distribution grid (point de référence mesure, also point de livraison).'),
  ('ban_address', 'BAN address',         '^[0-9]{5}_[0-9a-z]+_[0-9a-z_]+$',            'https://adresse.data.gouv.fr/base-adresse-nationale/{value}',     'ban',          'pack:fr', 'The identifier of an address in the Base Adresse Nationale.'),
  ('siren',       'SIREN',               '^[0-9]{9}$',                                 'https://annuaire-entreprises.data.gouv.fr/entreprise/{value}',    'sirene',       'pack:fr', 'The 9-digit identifier of a company in the national register.'),
  ('siret',       'SIRET',               '^[0-9]{14}$',                                'https://annuaire-entreprises.data.gouv.fr/etablissement/{value}', 'sirene',       'pack:fr', 'The 14-digit identifier of an establishment: SIREN and a 5-digit NIC.'),
  ('parcelle',    'Cadastral parcel',    '^[0-9][0-9AB][0-9]{3}[0-9A-Z]{3}[0-9A-Z]{2}[0-9]{4}$', 'https://cadastre.data.gouv.fr/map?parcelleId={value}',   'cadastre',     'pack:fr', 'The 14-character identifier of a cadastral parcel: municipality (5), prefix (3), section (2), number (4).'),
  ('rnb_id',      'RNB building',        '^[A-Z0-9]{12}$',                             'https://rnb.beta.gouv.fr/batiments/{value}',                      'rnb',          'pack:fr', 'The 12-character identifier of a building in the Référentiel National des Bâtiments.');
